sql-set.sql:
		INSERT INTO VersionTrack (
                    PlatformType,
                    VersionNumber,
                    ReleaseDate,
                    CreatedDate,
					ReleaseNotes,
					ReleasedBy,
					ReleasedTo
                ) 
                OUTPUT INSERTED.Id 
                VALUES (
                    @PlatformType,
                    @VersionNumber,
                    @ReleaseDate,
                    @CreatedDate,
                    @ReleaseNotes,
                    @ReleasedBy,
                    @ReleasedTo
                )
